"""YAML renderer — standard library only (uses repr-based serialization)."""

from plugins import PluginError, Renderer, register


def _yaml_value(v):
    """Return a YAML-safe string representation of a scalar value."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return str(v)
    # string
    s = str(v)
    # Quote if it could be misinterpreted
    if s in ("", "true", "false", "null", "yes", "no", "on", "off"):
        return f'"{s}"'
    if any(c in s for c in ":{}[]&*?|->!%@`,#"):
        return f'"{s}"'
    if s.startswith((" ", "\t")) or s.endswith((" ", "\t")):
        return f'"{s}"'
    return s


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines: list[str] = []
        for row in rows:
            lines.append("-")
            for key, value in row.items():
                lines.append(f"  {_yaml_value(key)}: {_yaml_value(value)}")
        return "\n".join(lines) + "\n"

